const $ = s => document.querySelector(s);
const app = $('#app'), dialog = $('#dialog');
const paths = {
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4 4"/>', bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>', users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3m1-16a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v2"/>', settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="8" cy="6" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="18" r="2"/>', arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', chevron:'<path d="m9 6 6 6-6 6"/>', plus:'<path d="M12 5v14M5 12h14"/>', check:'<path d="m5 12 4 4 10-10"/>', close:'<path d="m6 6 12 12M6 18 18 6"/>', pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>', external:'<path d="M14 4h6v6m0-6-9 9M10 5H5v14h14v-5"/>', phone:'<path d="m6 3 4 4-2 3a16 16 0 0 0 6 6l3-2 4 4-2 3C9 21 3 15 3 5Z"/>', whatsapp:'<path d="M20 11.5a8.5 8.5 0 0 1-12 7.7L3 21l1.8-5A8.5 8.5 0 1 1 20 11.5Z"/><path d="m9 7-1 2c0 3 4 6 6 6l2-1-2-2-1 1-3-3 1-1Z"/>', shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Z"/><path d="m8 12 3 3 5-6"/>', logout:'<path d="M9 4H4v16h5m6-13 5 5-5 5M9 12h11"/>', building:'<path d="M5 21V3h11v18M2 21h20m-6-10h4v10M8 7h1m3 0h1M8 11h1m3 0h1M8 15h1m3 0h1m-4 6v-3h4v3"/>', info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>', menu:'<path d="M4 6h16M4 12h16M4 18h16"/>', clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', truck:'<path d="M3 5h11v12H3Zm11 4h4l3 4v4h-7"/><circle cx="7" cy="18" r="2"/><circle cx="17" cy="18" r="2"/>', link:'<path d="m10 14 4-4m-5 6-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0m2 0 2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0"/>', key:'<circle cx="8" cy="9" r="5"/><path d="m12 13 8 8m-4-4 3-3m-6 0 3-3"/>', database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/>', refresh:'<path d="M20 4v5h-5M4 20v-5h5M5 8a8 8 0 0 1 13-3l2 4M4 15l2 4a8 8 0 0 0 13-3"/>', minus:'<path d="M5 12h14"/>'
};
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.info}</svg>`;
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));
const initials = name => name.split(' ').filter(Boolean).slice(0,2).map(n => n[0]).join('').toUpperCase();
const date = value => value ? new Intl.DateTimeFormat('pt-BR', { day:'2-digit', month:'2-digit', year:'numeric' }).format(new Date(value)) : '—';
const dateTime = value => value ? new Intl.DateTimeFormat('pt-BR', { dateStyle:'short', timeStyle:'short' }).format(new Date(value)) : '—';
const localDateTime = value => value ? new Date(new Date(value).getTime()-new Date(value).getTimezoneOffset()*60000).toISOString().slice(0,16) : '';
const brand = () => '<div class="brand"><img src="/favicon.svg" alt="" width="34" height="34"><div><strong>ARRUDA</strong><small>BOMBAS</small></div></div>';
const state = { user:null, view:'search', provider:false, records:[], users:[], filters:{}, page:1, priority:'', q:'', sort:'score', seller:'', generation:0, googlePlaces:[], whatsappTimer:null, inbox:[], inboxSelected:'', inboxQuery:'' };
const STATES = 'AC AL AP AM BA CE DF ES GO MA MT MS MG PA PB PR PE PI RJ RN RS RO RR SC SP SE TO'.split(' ');
const SEGMENTS = ['Concreteira','Bombeamento de concreto','Construtora','Locadora'];
const SIZES = ['Pequeno','Médio','Grande','Não informado'];
const STATUSES = ['Novo','Em contato','Qualificado','Sem interesse'];
const opts = (values, selected = '', first) => `${first != null ? `<option value="">${esc(first)}</option>` : ''}${values.map(v=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(v)}</option>`).join('')}`;
const input = (name,label,type='text',extra='') => `<label class="field"><span>${label}</span><input name="${name}" type="${type}" ${extra}></label>`;
const select = (name,label,values,selected='',first) => `<label class="field"><span>${label}</span><select name="${name}" aria-label="${label}">${opts(values,selected,first)}</select></label>`;
let toastTimer;
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`visible${error?' error':''}`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.className='',5000)}
async function api(route,method='GET',body){let res;try{res=await fetch(`/api${route}`,{method,headers:method==='GET'?{}:{'Content-Type':'application/json','X-Arruda-Request':'1'},body:body===undefined?undefined:JSON.stringify(body)})}catch{throw new Error('Sem conexão com o sistema. Verifique a conexão e tente novamente.')}const raw=await res.text();let data;try{data=JSON.parse(raw)}catch{throw new Error(`A API retornou erro ${res.status}. Verifique os logs e as variáveis na Vercel.`)}if(!res.ok){if(res.status===401&&route!='/login'){state.user=null;dialog.close();renderAuth()}throw new Error(data.error||'Não foi possível concluir.')}return data}
function renderAuth(needsSetup=false,tokenRequired=false){
 app.innerHTML=`<main id="main" class="auth-shell"><section class="auth-story">${brand()}<div class="auth-copy"><h1>Seu próximo cliente.<br><span>Mais perto.</span></h1><p>Encontre as empresas certas e transforme informação em boas conversas comerciais.</p><div class="auth-flow"><span>Encontre</span>${icon('chevron')}<span>Priorize</span>${icon('chevron')}<span>Conecte</span></div></div><div class="auth-foot">${icon('shield')}Prospecção comercial · Arruda Bombas</div></section><section class="auth-panel"><form class="auth-form stack" id="${needsSetup?'setup':'login'}"><div><h2>${needsSetup?'Prepare sua equipe.':'Bem-vindo de volta.'}</h2><p class="muted">${needsSetup?'Crie o primeiro administrador para começar.':'Entre para continuar sua prospecção.'}</p></div>${needsSetup?input('name','Seu nome','text','required autocomplete="name" maxlength="100"'):''}${input('email','E-mail','email','required autocomplete="username" placeholder="voce@empresa.com.br" maxlength="254"')}${input('password',needsSetup?'Crie uma senha':'Senha','password',`required autocomplete="${needsSetup?'new-password':'current-password'}" ${needsSetup?'minlength="12"':''} maxlength="128" placeholder="${needsSetup?'Pelo menos 12 caracteres':'Sua senha'}"`)}${needsSetup?input('confirm','Confirme a senha','password','required autocomplete="new-password" minlength="12" maxlength="128"'):''}${needsSetup&&tokenRequired?input('token','Chave de configuração','password','required autocomplete="off"'):''}<p class="form-error" role="alert"></p><button class="btn primary" type="submit">${needsSetup?'Criar administrador':'Entrar na plataforma'}${icon('arrow')}</button><p class="fine">${needsSetup?'Depois, adicione os vendedores em Usuários.':'Esqueceu sua senha? Solicite uma nova ao administrador.'}</p></form></section></main>`;
}
const viewNames = {search:'Encontrar empresas',leads:'Meus Leads',whatsapp:'WhatsApp Chat',users:'Usuários',settings:'Configurações',account:'Minha conta'};
function shell(){app.innerHTML=`<div class="app-shell"><aside class="sidebar" aria-label="Navegação principal">${brand()}<nav class="nav-group"><div class="nav-label">PROSPECÇÃO</div>${[['search','search','Encontrar empresas'],['leads','bookmark','Meus Leads'],['whatsapp','whatsapp','WhatsApp Chat']].map(([v,i,t])=>`<button class="nav-item ${state.view===v?'active':''}" data-nav="${v}" ${state.view===v?'aria-current="page"':''}>${icon(i)}${t}</button>`).join('')}${state.user.role==='admin'?`<div class="nav-label nav-group">GESTÃO</div><button class="nav-item ${state.view==='users'?'active':''}" data-nav="users">${icon('users')}Usuários</button>`:''}<button class="nav-item ${state.view==='settings'?'active':''}" data-nav="settings">${icon('settings')}Configurações</button></nav><div class="sidebar-bottom"><div class="sidebar-note">Boas oportunidades começam<br>com a empresa certa.</div><button class="nav-item" data-action="logout">${icon('logout')}Sair da plataforma</button></div></aside><div class="workspace"><header class="topbar"><button class="btn quiet icon-only mobile-menu" data-action="menu" aria-label="Abrir navegação" aria-expanded="false">${icon('menu')}</button><span class="head-mobile-brand">Arruda Bombas</span><div class="crumb">Comercial${icon('chevron')}<strong>${viewNames[state.view]}</strong></div><div class="user-menu"><span class="badge">Uso interno</span><span class="top-separator"></span><button class="btn quiet compact" data-nav="account" aria-label="Minha conta"><span class="avatar">${esc(initials(state.user.name))}</span><span class="user-copy"><strong>${esc(state.user.name)}</strong><span>${state.user.role==='admin'?'Administrador':'Vendedor'}</span></span></button></div></header><main id="main" class="page" tabindex="-1"></main></div></div>`}
function heading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div>${action?`<div class="heading-actions">${action}</div>`:''}</div>`}
function footer(){return `<footer class="page-foot"><span>${icon('shield')}Dados compartilhados com a equipe Arruda Bombas</span><span>Você conduz a conversa. Nenhuma mensagem é enviada automaticamente.</span></footer>`}
async function navigate(view){clearInterval(state.whatsappTimer);state.whatsappTimer=null;state.view=view;state.q='';state.priority='';state.page=1;shell();const generation=++state.generation;const main=$('#main');
 if(view==='search'||view==='leads') {main.innerHTML=heading(view==='search'?'Encontre sua próxima oportunidade.':'Meus Leads',view==='search'?'As empresas certas para levar a Arruda Bombas mais longe.':'Acompanhe contatos, interesses e próximos passos em um só lugar.',`<button class="btn" data-action="add-company">${icon('plus')}Cadastrar empresa</button>`)+(view==='search'?searchPanel():`<div class="connection-banner">${icon('users')}<span>Cada vendedor acompanha a própria carteira. Administradores visualizam a prospecção de toda a equipe.</span></div>`)+`<section class="results" id="results" aria-label="${view==='search'?'Empresas encontradas':'Leads da equipe'}"><div class="page-loading" role="status">Carregando empresas…</div></section>`+footer();try{const r=await api(view==='leads'?'/leads':'/companies?'+new URLSearchParams(state.filters));if(generation!==state.generation)return;state.records=r.companies;renderResults()}catch(e){if(generation===state.generation&&$('#results'))$('#results').innerHTML=`<div class="table-wrap empty"><h3>Não foi possível carregar a base</h3><p>${esc(e.message)}</p><button class="btn" data-action="reload">${icon('refresh')}Tentar novamente</button></div>`}}
 else if(view==='whatsapp'){main.innerHTML=heading('WhatsApp Chat','Converse com os clientes da sua carteira em um só lugar.')+`<section class="inbox" aria-label="Conversas do WhatsApp"><aside class="inbox-list"><div class="inbox-list-head"><div><h2>Conversas</h2><span id="inbox-count" class="small muted">Carregando…</span></div><span class="inbox-live" id="inbox-status">Verificando…</span></div><label class="inbox-search">${icon('search')}<input id="inbox-search" type="search" placeholder="Buscar cliente ou cidade" aria-label="Buscar conversa"></label><div id="inbox-contacts" class="inbox-contacts" role="list"><p class="muted small inbox-hint">Carregando clientes…</p></div></aside><div id="inbox-chat" class="inbox-chat"><div class="inbox-placeholder">${icon('whatsapp')}<h2>Selecione uma conversa</h2><p>Escolha um cliente à esquerda para ver as mensagens e responder.</p></div></div></section>`+footer();await loadInbox();if(generation===state.generation)state.whatsappTimer=setInterval(()=>{if(state.view==='whatsapp')refreshInbox()},10000)}
 else if(view==='users'){main.innerHTML=heading('Sua equipe, conectada.','Gerencie quem pode acessar a plataforma e prospectar.',`<button class="btn primary" data-action="add-user">${icon('plus')}Adicionar usuário</button>`)+`<div id="users-content" class="page-loading">Carregando equipe…</div>`+footer();try{const r=await api('/users');if(generation!==state.generation)return;state.users=r.users;$('#users-content').className='table-wrap';$('#users-content').innerHTML=`<table><thead><tr><th>Usuário</th><th>Permissão</th><th>Acesso</th><th>Criado em</th><th><span class="small">Gerenciar</span></th></tr></thead><tbody>${r.users.map(u=>`<tr><td><div class="company-cell"><span class="avatar">${esc(initials(u.name))}</span><div><strong>${esc(u.name)} ${u.id===state.user.id?'<span class="muted">(você)</span>':''}</strong><div class="small muted">${esc(u.email)}</div></div></div></td><td>${u.role==='admin'?'Administrador':'Vendedor'}</td><td><span class="status ${u.active?'qualified':''}">${u.active?'Ativo':'Desativado'}</span></td><td>${date(u.createdAt)}</td><td><button class="btn compact" data-user="${u.id}">Gerenciar${icon('chevron')}</button></td></tr>`).join('')}</tbody></table>`}catch(e){if($('#users-content'))$('#users-content').textContent=e.message}}
 else if(view==='settings'){main.innerHTML=heading('Configurações','Transparência sobre os dados e os critérios de prospecção.')+`<div class="settings-grid"><section class="settings-block"><h2>Fonte de empresas</h2><p>Empresas reais precisam vir de uma fonte conectada ou de um cadastro verificado pela equipe.</p><span class="badge">${state.provider?'Fonte conectada':'Aguardando definição da fonte'}</span><div class="notice" style="">${state.provider?'As buscas consultam a fonte configurada. Confira a origem e a atualidade de cada informação antes de abordar.':'A busca externa ainda não está disponível. O cadastro manual e a pesquisa na base da equipe já podem ser utilizados.'}</div><dl><dt>Busca na base da equipe</dt><dd>Disponível</dd><dt>Busca de novas empresas</dt><dd>${state.provider?'Conectada':'Pendente'}</dd><dt>Mensagens automáticas</dt><dd>Não são enviadas</dd></dl><p class="rule-note">A conexão é configurada pelo responsável técnico após a escolha do fornecedor de dados.</p></section><section class="settings-block"><h2>Como calculamos o potencial</h2><p>A pontuação organiza o trabalho comercial. Ela não representa probabilidade de compra.</p><table class="rule-table"><tbody><tr><td>Segmento</td><td>Até 30 pontos</td></tr><tr><td>Porte</td><td>Até 20 pontos</td></tr><tr><td>Bombeamento de concreto</td><td>25 pontos</td></tr><tr><td>Frota própria</td><td>15 pontos</td></tr><tr><td>Várias unidades</td><td>10 pontos</td></tr></tbody></table><div class="result-summary"><span><span class="priority a">A</span>75–100</span><span><span class="priority b">B</span>45–74</span><span><span class="priority c">C</span>0–44</span></div><p class="rule-note">Concreteira: 25; bombeamento: 30; construtora ou locadora: 15. Porte grande: 20; médio: 12; pequeno: 5. Informações desconhecidas não somam pontos. Critérios iniciais sujeitos à validação comercial.</p></section></div>`+whatsappSettings()+footer();loadWhatsAppStatus();state.whatsappTimer=setInterval(()=>{if(state.view==='settings')loadWhatsAppStatus()},5000)}
 else if(view==='account'){main.innerHTML=heading('Minha conta','Mantenha seu acesso protegido.')+`<section class="settings-block account-column"><h2>${esc(state.user.name)}</h2><p>${esc(state.user.email)}</p>${passwordForm()}</section>`}
}
function searchPanel(){return `${!state.provider?`<div class="connection-banner">${icon('info')}<span><strong>Estamos preparando a busca externa.</strong> Por enquanto, pesquise as empresas cadastradas pela equipe.</span><button class="text-btn" data-nav="settings">Ver detalhes</button></div>`:''}<form id="filters" class="filter-panel"><div class="section-title"><h2>${icon('settings')}Defina o perfil da sua busca</h2><button type="button" class="text-btn small" data-action="clear">Limpar filtros</button></div><div class="filter-grid">${select('state','Estado',STATES,state.filters.state,'Todos os estados')}${input('city','Cidade','text',`placeholder="Todas as cidades" maxlength="100" value="${esc(state.filters.city||'')}"`)}${select('segment','Segmento',SEGMENTS,state.filters.segment,'Todos os segmentos')}${select('size','Porte da empresa',SIZES,state.filters.size,'Todos os portes')}</div><div class="filter-actions"><p>${icon('info')}Quanto mais específico o perfil, mais focada a prospecção.</p><div class="filter-buttons">${state.provider?`<button class="btn" type="button" data-action="external-search">${icon('external')}Buscar novas empresas</button>`:''}<button class="btn primary" type="submit">${icon('search')}Buscar na base</button></div></div></form>`}
function renderResults(){const el=$('#results');if(!el)return;let list=state.records.filter(c=>(!state.priority||c.priority===state.priority)&&(state.view!=='leads'||!state.seller||c.savedBy===state.seller)&&(!state.q||`${c.name} ${c.city}`.toLocaleLowerCase('pt-BR').includes(state.q.toLocaleLowerCase('pt-BR'))));if(state.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));if(state.sort==='recent')list.sort((a,b)=>(b.savedAt||b.verifiedAt).localeCompare(a.savedAt||a.verifiedAt));const max=Math.max(1,Math.ceil(list.length/15));state.page=Math.min(state.page,max);const items=list.slice((state.page-1)*15,state.page*15), leads=state.view==='leads';
 const active=document.activeElement?.id,position=active==='record-search'?document.activeElement.selectionStart:null;
 el.innerHTML=`<div class="results-toolbar"><div class="results-title"><h2>${leads?(state.user.role==='admin'?'Leads da equipe':'Meus leads'):'Empresas na sua base'}</h2><span class="count-pill">${list.length}</span></div><div class="result-options">${leads&&state.user.role==='admin'?`<select id="seller-filter" aria-label="Filtrar por vendedor"><option value="">Todos os vendedores</option>${[...new Map(state.records.map(c=>[c.savedBy,c.savedByName])).entries()].map(([id,name])=>`<option value="${esc(id)}" ${state.seller===id?'selected':''}>${esc(name)}</option>`).join('')}</select>`:''}<div class="search-wrap">${icon('search')}<input id="record-search" class="search-input" aria-label="Filtrar por nome ou cidade" placeholder="Nome ou cidade…" value="${esc(state.q)}"></div><select id="sort" aria-label="Ordenar empresas">${opts(['score','name','recent'].map(v=>v),state.sort).replace('>score<','>Maior potencial<').replace('>name<','>Nome A–Z<').replace('>recent<','>Mais recentes<')}</select></div></div><div class="result-summary"><span>${state.records.length} ${leads?'leads salvos':'empresas cadastradas'}</span><button class="text-btn small ${state.priority?'':'muted'}" data-priority="">Todas</button>${['A','B','C'].map(p=>`<button class="btn quiet compact" aria-pressed="${state.priority===p}" data-priority="${p}"><span class="dot ${p.toLowerCase()}"></span>Prioridade ${p}<strong>${state.records.filter(c=>c.priority===p).length}</strong></button>`).join('')}</div>${Object.entries(state.filters).filter(([,v])=>v).length&&!leads?`<div class="chips">${Object.values(state.filters).filter(Boolean).map(v=>`<span class="chip">${esc(v)}</span>`).join('')}</div>`:''}<div class="table-wrap">${!list.length?`<div class="empty"><div class="empty-symbol">${icon(leads?'bookmark':'building')}</div><h3>${state.q||state.priority||Object.values(state.filters).some(Boolean)?'Nenhuma empresa com esse perfil':leads?'Suas próximas oportunidades ficam aqui.':'Vamos encontrar os primeiros clientes?'}</h3><p>${state.q||state.priority||Object.values(state.filters).some(Boolean)?'Ajuste os filtros para ampliar a busca na base da equipe.':leads?'Encontre uma empresa e salve em Meus Leads. Você poderá registrar os contatos e o equipamento de interesse.':'Cadastre uma empresa com informações verificadas. O sistema calcula o potencial e organiza os contatos para a equipe.'}</p><button class="btn ${leads?'':'primary'}" data-action="${leads?'go-search':state.q||state.priority||Object.values(state.filters).some(Boolean)?'clear':'add-company'}">${icon(leads?'search':'plus')}${leads?'Encontrar empresas':state.q||state.priority||Object.values(state.filters).some(Boolean)?'Limpar filtros':'Cadastrar primeira empresa'}</button></div>`:`<table><thead><tr><th>Empresa</th><th>Perfil</th><th>Potencial</th><th>${leads?'Prospecção':'Estrutura'}</th><th>${leads?'Salvo por':'Contato'}</th><th>Ações</th></tr></thead><tbody>${items.map(c=>`<tr><td><div class="company-cell"><span class="company-initials">${esc(initials(c.name))}</span><div><button class="company-name" data-detail="${c.id}">${esc(c.name)}</button><div class="company-city">${icon('pin')}${esc(c.city)} · ${esc(c.state)}</div></div></div></td><td>${esc(c.segment)}<div class="small muted">${c.size==='Não informado'?'Porte não informado':`Porte ${esc(c.size.toLowerCase())}`}</div></td><td><span class="priority ${c.priority.toLowerCase()}">${c.priority}</span><span class="score">${c.score}<small>/100</small></span></td><td>${leads?`<span class="status ${c.status==='Qualificado'?'qualified':c.status==='Em contato'?'contact':''}">${esc(c.status)}</span>${c.equipmentInterest?`<div class="small muted lead-interest">${esc(c.equipmentInterest)}</div>`:''}`:signal('Bombeamento',c.pumping)+signal('Frota própria',c.fleet)}</td><td>${leads?`${esc(c.savedByName)}<div class="small muted">${date(c.savedAt)}</div>`:c.phone?`${esc(c.phone)}<div class="small muted">${c.whatsapp?'WhatsApp disponível':'WhatsApp não informado'}</div>`:'<span class="muted">Não informado</span>'}</td><td><div class="actions">${c.saved?`<span class="saved-tag" title="Salvo por ${esc(c.savedByName)}">${icon('check')}${leads?'':'Salvo'}</span>`:`<button class="btn compact" data-save="${c.id}" aria-label="Salvar ${esc(c.name)}">${icon('bookmark')}Salvar</button>`}<button class="btn quiet icon-only compact" data-detail="${c.id}" aria-label="Ver detalhes de ${esc(c.name)}">${icon('chevron')}</button></div></td></tr>`).join('')}</tbody></table><div class="table-footer"><span>${(state.page-1)*15+1}–${Math.min(state.page*15,list.length)} de ${list.length}${list.length===1000?' · limite de 1.000; refine os filtros':''}</span><div class="pagination"><button class="btn compact" data-page="${state.page-1}" ${state.page===1?'disabled':''}>Anterior</button><span>${state.page} / ${max}</span><button class="btn compact" data-page="${state.page+1}" ${state.page>=max?'disabled':''}>Próxima</button></div></div>`}</div>`;
 if(active==='record-search'){$('#record-search').focus();$('#record-search').setSelectionRange(position,position)}
}
function signal(label,value){return `<span class="signal ${value===1?'yes':''}">${icon(value===1?'check':value===0?'minus':'info')}${label}${value==null?' · não informado':value===0?' · não':''}</span>`}
function openDialog(title,body,sheet=false){dialog.className=sheet?'sheet':'';dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="btn quiet icon-only" data-action="close" aria-label="Fechar">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();dialog.scrollTop=0}
function addCompany(place={}){openDialog('Cadastrar empresa',`<form id="company-form"><p class="muted small">Use dados conferidos em uma fonte pública. Deixe como não informado o que não foi possível verificar.</p><div class="form-grid">${input('name','Nome da empresa *','text',`required maxlength="160" value="${esc(place.name||'')}"`)}${input('cnpj','CNPJ (opcional)','text','maxlength="18" placeholder="00.000.000/0000-00"')}${input('city','Cidade *','text',`required maxlength="100" value="${esc(state.filters.city||'')}"`)}${select('state','Estado *',STATES,state.filters.state||'SP')}${select('segment','Segmento *',SEGMENTS,state.filters.segment)}${select('size','Porte',SIZES,'Não informado')}${input('phone','Telefone','tel',`maxlength="30" placeholder="(11) 0000-0000" value="${esc(place.phone||'')}"`)}${input('whatsapp','WhatsApp com 55 e DDD','tel','maxlength="20" placeholder="5511999999999"')}${input('website','Site','url',`placeholder="https://" maxlength="500" value="${esc(place.website||'')}"`)}${input('sourceUrl','Link da fonte consultada *','url',`required placeholder="https://" maxlength="500" value="${esc(place.mapsUrl||place.website||'')}"`)}${['pumping','fleet','branches'].map((k,i)=>`<label class="field"><span>${['Trabalha com bombeamento?','Possui frota própria?','Possui várias unidades?'][i]}</span><select name="${k}"><option value="">Não informado</option><option value="1">Sim, verificado</option><option value="0">Não, verificado</option></select></label>`).join('')}<label class="field full"><span>Informações sobre a estrutura</span><textarea name="structure" maxlength="3000" placeholder="Descreva apenas informações encontradas na fonte."></textarea></label><p class="form-error full" role="alert"></p></div><div class="dialog-foot"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary">Cadastrar empresa</button></div></form>`)}
async function detail(id){const c=state.records.find(c=>c.id===id);if(!c)return;let activities=[];if(c.saved){try{activities=(await api(`/leads/${c.id}/activities`)).activities}catch{activities=[]}}const message=encodeURIComponent(`Olá, falo da Arruda Bombas Hidráulicas. Gostaria de conversar com a ${c.name}.`);openDialog(c.name,`<p class="detail-subtitle">${esc(c.city)} · ${esc(c.state)} &nbsp; / &nbsp; ${esc(c.segment)}</p><div class="detail-score"><span class="priority ${c.priority.toLowerCase()}">${c.priority}</span><div><span class="score">${c.score}<small>/100</small></span><p class="small muted">Prioridade ${c.priority}</p></div><span class="muted">${c.unknown?`${c.unknown} informações de estrutura ou porte não confirmadas.`:'Todos os critérios foram informados.'}</span></div><div class="detail-actions">${c.whatsapp?`<a class="btn whatsapp" target="_blank" rel="noopener noreferrer" href="https://wa.me/${esc(c.whatsapp)}?text=${message}">${icon('whatsapp')}Abrir WhatsApp${icon('external')}</a>`:'<span class="badge">WhatsApp não informado</span>'}${!c.saved?`<button class="btn primary" data-save="${c.id}">${icon('bookmark')}Salvar lead</button>`:`<span class="saved-tag">${icon('check')}Responsável: ${esc(c.savedByName)}</span>`}</div>${c.saved&&c.whatsapp?whatsappPanel(c):''}<section class="detail-section"><h3>Informações da empresa</h3><dl class="detail-grid"><div><dt>Telefone</dt><dd>${c.phone?esc(c.phone):'Não informado'}</dd></div><div><dt>Porte</dt><dd>${esc(c.size)}</dd></div><div><dt>CNPJ</dt><dd>${esc(c.cnpj||'Não informado')}</dd></div><div><dt>Site</dt><dd>${c.website?`<a class="source-link" href="${esc(c.website)}" target="_blank" rel="noopener noreferrer">Visitar site${icon('external')}</a>`:'Não informado'}</dd></div></dl></section>${c.saved?`<section class="detail-section prospect-card"><div class="prospect-title"><div><h3>Registrar prospecção</h3><p class="small muted">Responsável: ${esc(c.savedByName)}.</p></div>${c.lastContactAt?`<span class="badge">Último contato ${date(c.lastContactAt)}</span>`:''}</div>${state.user.role==='admin'||c.savedBy===state.user.id?`<form id="lead-form" data-id="${c.id}" data-version="${c.version}" class="prospect-form"><div class="form-grid">${select('status','Etapa da prospecção',STATUSES,c.status)}${input('equipmentInterest','Equipamento de interesse','text',`maxlength="120" placeholder="Ex.: bomba lança 36 m" value="${esc(c.equipmentInterest||'')}"`)}<label class="field"><span>Resultado do contato</span><select name="contactResult"><option value="">Selecione ao registrar contato</option>${['Contato iniciado','Sem resposta','Conversa em andamento','Proposta solicitada','Sem interesse'].map(v=>`<option>${v}</option>`).join('')}</select></label>${input('nextContactAt','Próximo contato','datetime-local',`value="${localDateTime(c.nextContactAt)}"`)}<label class="field full"><span>Anotações</span><textarea name="notes" maxlength="5000" placeholder="Registre o que foi conversado e o próximo passo.">${esc(c.notes)}</textarea></label></div><p class="form-error" role="alert"></p><button class="btn primary">Salvar prospecção</button></form>`:'<p class="muted small">Somente o responsável pode atualizar este lead.</p>'}</section><section class="detail-section"><h3>Histórico de contatos</h3><div class="activity-list">${activities.length?activities.map(a=>`<article class="activity-item"><span class="activity-dot"></span><div><strong>${esc(a.contactResult)}</strong><span>${esc(a.userName)} · ${dateTime(a.createdAt)}</span>${a.equipmentInterest?`<p>Interesse: ${esc(a.equipmentInterest)}</p>`:''}${a.notes?`<p>${esc(a.notes)}</p>`:''}</div></article>`).join(''):'<p class="muted small">Nenhum contato registrado ainda.</p>'}</div></section>`:''}<section class="detail-section"><h3>Origem das informações</h3><a class="source-link" href="${esc(c.sourceUrl)}" target="_blank" rel="noopener noreferrer">Consultar fonte${icon('external')}</a><p class="small muted">Cadastro em ${date(c.verifiedAt)}. Confira a atualidade dos dados antes de entrar em contato.</p></section>`,true);if(c.saved&&c.whatsapp)loadWhatsAppConversation(c.id)}
function addUser(){openDialog('Adicionar usuário',`<form id="user-form" class="stack"><p class="muted small">Crie o acesso e compartilhe a senha provisória diretamente com a pessoa. Ela deverá trocar a senha no primeiro acesso.</p>${input('name','Nome','text','required maxlength="100"')}${input('email','E-mail','email','required autocomplete="off" maxlength="254"')}${input('password','Senha provisória','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="password-help">Pelo menos 12 caracteres.</p><label class="field"><span>Permissão</span><select name="role"><option value="seller">Vendedor — busca e gerencia leads</option><option value="admin">Administrador — também gerencia usuários</option></select></label><p class="form-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary">Criar usuário</button></div></form>`)}
function manageUser(id){const u=state.users.find(u=>u.id===id);openDialog('Gerenciar acesso',`<form id="manage-user" data-id="${u.id}" class="stack"><div><h3>${esc(u.name)}</h3><p class="muted small">${esc(u.email)}</p></div><label class="field"><span>Permissão</span><select name="role"><option value="seller" ${u.role==='seller'?'selected':''}>Vendedor</option><option value="admin" ${u.role==='admin'?'selected':''}>Administrador</option></select></label><label class="field"><span>Acesso à plataforma</span><select name="active"><option value="true" ${u.active?'selected':''}>Ativo</option><option value="false" ${!u.active?'selected':''}>Desativado</option></select></label>${input('password','Nova senha provisória (opcional)','password','minlength="12" maxlength="128" autocomplete="new-password"')}<p class="small muted">Deixe em branco para manter a senha. Alterações encerram as sessões deste usuário.</p><p class="form-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary">Salvar alterações</button></div></form>`)}
function passwordForm(){return `<form id="password-form" class="stack">${state.user.mustChange?'<p class="notice">Por segurança, substitua a senha provisória antes de continuar.</p>':''}${input('currentPassword','Senha atual','password','required autocomplete="current-password" maxlength="128"')}${input('password','Nova senha','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${input('confirm','Confirme a nova senha','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="form-error" role="alert"></p><button class="btn primary">${icon('key')}Atualizar senha</button></form>`}
async function saveLead(id,button){button.disabled=true;try{const r=await api('/leads','POST',{companyId:id});toast(r.duplicate?'Esta empresa já possui um responsável.':'Lead salvo na sua carteira.');const opened=dialog.open;await refreshRecords();if(opened)detail(id)}catch(e){toast(e.message,true)}finally{button.disabled=false}}
async function refreshRecords(){const view=state.view;const r=await api(view==='leads'?'/leads':'/companies?'+new URLSearchParams(state.filters));if(state.view!==view)return;state.records=r.companies;renderResults()}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a[data-nav]');if(!b)return;if(b.dataset.nav){if(state.user.mustChange&&b.dataset.nav!=='account'){toast('Atualize sua senha para continuar.',true);return}await navigate(b.dataset.nav);return}if(b.dataset.detail){detail(b.dataset.detail);return}if(b.dataset.googlePlace){addCompany(state.googlePlaces[Number(b.dataset.googlePlace)]);return}if(b.dataset.save){await saveLead(b.dataset.save,b);return}if(b.dataset.user){manageUser(b.dataset.user);return}if(b.hasAttribute('data-priority')){state.priority=b.dataset.priority;state.page=1;renderResults();return}if(b.dataset.page){state.page=Number(b.dataset.page);renderResults();return}
 switch(b.dataset.action){case'close':dialog.close();break;case'menu':{const open=$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open));break}case'logout':try{await api('/logout','POST',{});state.user=null;renderAuth()}catch(e){toast(e.message,true)}break;case'add-company':addCompany();break;case'add-user':addUser();break;case'go-search':await navigate('search');break;case'clear':state.filters={};state.q='';state.priority='';await navigate(state.view);break;case'reload':await navigate(state.view);break;case'external-search':{const form=$('#filters'),filters=Object.fromEntries(new FormData(form));b.disabled=true;b.textContent='Recherche en cours…'.replace('Recherche en cours','Buscando empresas');try{const r=await api('/search','POST',filters);state.filters=filters;state.records=r.companies;state.page=1;renderResults();toast(`${r.imported} empresas adicionadas.${r.skipped?` ${r.skipped} registros sem dados válidos foram ignorados.`:''}`)}catch(e){toast(e.message,true)}finally{b.disabled=false;b.innerHTML=icon('external')+'Buscar novas empresas'}break}}
});
document.addEventListener('input',e=>{if(e.target.id==='record-search'){state.q=e.target.value;state.page=1;renderResults()}});
document.addEventListener('change',e=>{if(e.target.id==='sort'){state.sort=e.target.value;renderResults()}if(e.target.id==='seller-filter'){state.seller=e.target.value;state.page=1;renderResults()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),error=form.querySelector('.form-error');if(error)error.textContent='';const button=form.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=true;
 try{switch(form.id){case'login':case'setup':{if(form.id==='setup'&&data.password!==data.confirm)throw new Error('As senhas não coincidem.');const r=await api(form.id==='setup'?'/setup':'/login','POST',data);state.user=r.user;await navigate(state.user.mustChange?'account':'search');break}case'filters':{state.filters=data;state.page=1;await refreshRecords();break}case'company-form':{const r=await api('/companies','POST',data);dialog.close();toast(r.duplicate?'Esta empresa já está cadastrada. Nenhuma duplicata foi criada.':'Empresa cadastrada. O potencial já foi calculado.');state.filters={};await navigate('search');detail(r.id);break}case'user-form':await api('/users','POST',data);dialog.close();toast('Usuário criado. Compartilhe a senha provisória diretamente.');await navigate('users');break;case'manage-user':{await api(`/users/${form.dataset.id}`,'PATCH',{...data,active:data.active==='true'});dialog.close();if(form.dataset.id===state.user.id){state.user=null;renderAuth();toast('Acesso atualizado. Entre novamente.')}else{toast('Acesso atualizado.');await navigate('users')}break}case'lead-form':await api(`/leads/${form.dataset.id}`,'PATCH',{...data,nextContactAt:data.nextContactAt?new Date(data.nextContactAt).toISOString():null,version:Number(form.dataset.version)});toast('Acompanhamento atualizado.');await refreshRecords();detail(form.dataset.id);break;case'password-form':if(data.password!==data.confirm)throw new Error('As senhas não coincidem.');await api('/password','POST',data);state.user.mustChange=false;toast('Senha atualizada.');await navigate('search');break}}
 catch(e){if(error)error.textContent=e.message;else toast(e.message,true)}finally{if(button)button.disabled=false}
});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('.sidebar')?.classList.remove('open');$('.mobile-menu')?.setAttribute('aria-expanded','false')}});
async function boot(){try{const s=await api('/session');state.user=s.user;state.provider=s.providerConfigured;if(s.user)await navigate(s.user.mustChange?'account':'search');else renderAuth(s.needsSetup,s.setupTokenRequired)}catch(e){app.innerHTML=`<main id="main" class="boot"><h1>Não foi possível conectar</h1><p>${esc(e.message)}</p><a class="btn" href="/">Tentar novamente</a></main>`}}
boot();

function forgotPassword(){openDialog('Recuperar senha',`<form id="forgot-password" class="stack"><p class="muted">Informe seu e-mail. Se ele estiver entre as três contas ativas, enviaremos um link para definir uma nova senha.</p>${input('email','E-mail','email','required autocomplete="email" maxlength="254"')}<p class="form-error" role="alert"></p><div class="dialog-foot"><button type="button" class="btn" data-action="close">Cancelar</button><button class="btn primary">Enviar link</button></div></form>`)}
function renderResetPassword(token){app.innerHTML=`<main id="main" class="auth-shell"><section class="auth-story">${brand()}<div class="auth-copy"><h1>Defina sua<br><span>nova senha.</span></h1><p>Escolha uma senha segura para entrar na plataforma.</p></div></section><section class="auth-panel"><form class="auth-form stack" id="reset-password" data-token="${esc(token)}"><div><h2>Redefinir senha</h2><p class="muted">Use pelo menos 12 caracteres.</p></div>${input('password','Nova senha','password','required minlength="12" maxlength="128" autocomplete="new-password"')}${input('confirm','Confirme a nova senha','password','required minlength="12" maxlength="128" autocomplete="new-password"')}<p class="form-error" role="alert"></p><button class="btn primary" type="submit">Salvar nova senha${icon('arrow')}</button><button class="btn quiet" type="button" data-action="back-login">Voltar ao login</button></form></section></main>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action==='forgot-password'){forgotPassword()}if(b.dataset.action==='back-login'){history.replaceState({},'',location.pathname);renderAuth()}});
document.addEventListener('submit',async e=>{const form=e.target;if(!(form instanceof HTMLFormElement))return;if(form.id!=='forgot-password'&&form.id!=='reset-password')return;e.preventDefault();const data=Object.fromEntries(new FormData(form)),error=form.querySelector('.form-error'),button=form.querySelector('button[type="submit"],button:not([type])');if(error)error.textContent='';if(button)button.disabled=true;try{if(form.id==='forgot-password'){await api('/forgot-password','POST',data);dialog.close();toast('Se o e-mail estiver autorizado, o link foi enviado.')}else{if(data.password!==data.confirm)throw new Error('As senhas não coincidem.');await api('/reset-password','POST',{token:form.dataset.token,password:data.password});history.replaceState({},'',location.pathname);renderAuth();toast('Senha redefinida. Entre para continuar.')}}catch(err){if(error)error.textContent=err.message;else toast(err.message,true)}finally{if(button)button.disabled=false}});
const resetToken=new URLSearchParams(location.search).get('reset');if(resetToken&&/^[a-f0-9]{64}$/.test(resetToken)){const waitForBoot=setInterval(()=>{if(document.readyState==='complete'){clearInterval(waitForBoot);renderResetPassword(resetToken)}},10)}
const accessObserver=new MutationObserver(()=>{const login=$('#login');if(login&&!login.querySelector('[data-action="forgot-password"]')){const hint=document.createElement('button');hint.type='button';hint.className='btn quiet compact';hint.dataset.action='forgot-password';hint.textContent='Esqueceu sua senha?';login.querySelector('.fine')?.replaceWith(hint)}const add=[...document.querySelectorAll('[data-action="add-user"]')];add.forEach(button=>{button.closest('.page-head-actions')?.remove();button.remove()})});accessObserver.observe(app,{childList:true,subtree:true});
function googleResults(items){state.googlePlaces=items;openDialog('Empresas encontradas no Google Maps',`<p class="muted small">Confira os dados e cadastre somente as empresas que fizerem sentido para a prospecção. Resultados do Google Maps não são salvos automaticamente.</p><div class="stack">${items.length?items.map((p,i)=>`<section class="detail-section"><h3>${esc(p.name)}</h3><p class="small muted">${esc(p.address||'Endereço não informado')}</p>${p.phone?`<p class="small">${esc(p.phone)}</p>`:''}<div class="detail-actions">${p.mapsUrl?`<a class="btn compact" target="_blank" rel="noopener noreferrer" href="${esc(p.mapsUrl)}">Abrir no Maps${icon('external')}</a>`:''}${p.website?`<a class="btn compact" target="_blank" rel="noopener noreferrer" href="${esc(p.website)}">Site${icon('external')}</a>`:''}<button class="btn compact primary" data-google-place="${i}">Cadastrar e prospectar</button></div></section>`).join(''):'<p>Nenhuma empresa foi encontrada para estes filtros.</p>'}</div><p class="small muted">Dados fornecidos por Google Maps.</p>`)}
document.addEventListener('click',async e=>{const button=e.target.closest('[data-action="external-search"]');if(!button)return;e.stopImmediatePropagation();const form=$('#filters'),filters=Object.fromEntries(new FormData(form));button.disabled=true;try{const result=await api('/google-places','POST',filters);googleResults(result.places)}catch(err){toast(err.message,true)}finally{button.disabled=false}},true);

function whatsappSettings(){return `<section class="settings-block wa-settings"><div class="wa-heading"><div><h2>WhatsApp da empresa</h2><p>Conecte o número da empresa para conversar com os leads dentro do CRM.</p></div><span class="badge" id="wa-settings-status">Verificando…</span></div><div id="wa-settings-qr" class="wa-qr"><p class="muted small">Carregando conexão…</p></div><button class="btn compact" type="button" data-action="wa-refresh">Atualizar conexão</button></section>`}
async function loadWhatsAppStatus(){const badge=$('#wa-settings-status'),qrBox=$('#wa-settings-qr');if(!badge||!qrBox)return;try{const result=await api('/whatsapp/status');if(!badge.isConnected)return;badge.textContent=result.status==='connected'?'Conectado':result.status==='qr'?'Aguardando QR Code':'Conectando';qrBox.innerHTML=result.status==='connected'?`<p class="wa-success">${icon('check')} Número conectado${result.phone?' · +'+esc(result.phone):''}</p>`:result.qr&&state.user.role==='admin'?`<p class="small muted">No celular da empresa, abra <strong>Aparelhos conectados → Conectar aparelho</strong> e leia o QR Code.</p><img src="${esc(result.qr)}" alt="QR Code para conectar o WhatsApp da empresa" width="260" height="260"><p class="small muted">O QR Code muda periodicamente nesta tela.</p>`:'<p class="muted small">Aguardando conexão do WhatsApp da empresa.</p>'}catch(error){if(!badge.isConnected)return;badge.textContent='Indisponível';qrBox.innerHTML=`<p class="data-error small">${esc(error.message)}</p>`}}
function whatsappPanel(c){return `<section class="detail-section wa-panel" aria-label="Conversa pelo WhatsApp"><div class="wa-heading"><div><h3>Conversa pelo WhatsApp</h3><p class="small muted">Número da empresa conectado ao CRM.</p></div><span class="badge" id="wa-chat-status">Verificando…</span></div><div id="wa-thread" class="wa-thread" role="log" aria-live="polite"><p class="muted small">Carregando mensagens…</p></div><form id="wa-compose" data-id="${esc(c.id)}"><label class="field"><span>Mensagem</span><textarea name="text" maxlength="3000" placeholder="Digite sua mensagem" required></textarea></label><p class="form-error" role="alert"></p><button class="btn primary" disabled>${icon('whatsapp')}Enviar pelo WhatsApp</button></form></section>`}
async function loadWhatsAppConversation(id){const thread=$('#wa-thread'),badge=$('#wa-chat-status'),form=$('#wa-compose');if(!thread||!form)return;try{const result=await api(`/whatsapp/leads/${id}`);if(!thread.isConnected)return;badge.textContent=result.status==='connected'?'Conectado':'Desconectado';form.querySelector('button').disabled=result.status!=='connected';thread.innerHTML=result.messages.length?result.messages.map(m=>`<article class="wa-bubble ${m.direction==='out'?'out':'in'}"><p>${esc(m.body)}</p><span>${m.direction==='out'?'Enviada por '+esc(m.userName||'vendedor'):'Recebida'} · ${dateTime(m.createdAt)}</span></article>`).join(''):`<p class="muted small">${result.status==='connected'?'Nenhuma mensagem registrada. Escreva a primeira mensagem abaixo.':'O número da empresa ainda não está conectado. Veja o QR Code em Configurações.'}</p>`;thread.scrollTop=thread.scrollHeight;if(!result.messages.length&&!form.elements.text.value)form.elements.text.value=`Olá, falo da Arruda Bombas Hidráulicas. Gostaria de conversar com a ${state.records.find(c=>c.id===id)?.name||'sua empresa'}.`}catch(error){if(!thread.isConnected)return;badge.textContent='Indisponível';thread.innerHTML=`<p class="data-error small">${esc(error.message)}</p>`;form.querySelector('button').disabled=true}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-action="wa-refresh"]');if(button)loadWhatsAppStatus()},true);
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='wa-compose')return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button'),error=form.querySelector('.form-error'),body=form.elements.text.value.trim();if(!body)return;button.disabled=true;error.textContent='';try{await api(`/whatsapp/leads/${form.dataset.id}`,'POST',{text:body});form.elements.text.value='';await loadWhatsAppConversation(form.dataset.id)}catch(err){error.textContent=err.message;button.disabled=false}},true);

async function loadInbox(){try{const [list,status]=await Promise.all([api('/whatsapp/conversations'),api('/whatsapp/status')]);if(state.view!=='whatsapp')return;state.inbox=list.conversations;renderInboxList();const badge=$('#inbox-status');badge.textContent=status.status==='connected'?'Conectado':'Desconectado';badge.classList.toggle('connected',status.status==='connected');if(state.inboxSelected&&state.inbox.some(c=>c.id===state.inboxSelected))await openInboxChat(state.inboxSelected);else if(state.inbox.length)await openInboxChat(state.inbox[0].id);else $('#inbox-chat').innerHTML=`<div class="inbox-placeholder">${icon('whatsapp')}<h2>Nenhum cliente com WhatsApp</h2><p>Salve um lead com número de WhatsApp para começar uma conversa.</p><button class="btn" data-nav="search">Encontrar empresas</button></div>`}catch(error){if(state.view==='whatsapp')$('#inbox-contacts').innerHTML=`<p class="inbox-error">${esc(error.message)}</p>`}}
function renderInboxList(){const host=$('#inbox-contacts');if(!host)return;const q=state.inboxQuery.toLocaleLowerCase('pt-BR'),list=state.inbox.filter(c=>`${c.name} ${c.city} ${c.whatsapp}`.toLocaleLowerCase('pt-BR').includes(q));$('#inbox-count').textContent=`${state.inbox.length} cliente${state.inbox.length===1?'':'s'}`;host.innerHTML=list.length?list.map(c=>`<button class="inbox-contact ${state.inboxSelected===c.id?'active':''}" data-inbox-id="${esc(c.id)}" role="listitem" aria-current="${state.inboxSelected===c.id?'true':'false'}"><span class="avatar">${esc(initials(c.name))}</span><span class="inbox-contact-main"><span class="inbox-contact-line"><strong>${esc(c.name)}</strong><time>${c.lastAt?date(c.lastAt):''}</time></span><span class="inbox-contact-preview">${c.lastBody?`${c.lastDirection==='out'?'Você: ':''}${esc(c.lastBody)}`:`${esc(c.city)} · ${esc(c.state)} · Sem mensagens`}</span></span></button>`).join(''):`<p class="inbox-hint muted small">${state.inbox.length?'Nenhum cliente corresponde à busca.':'Ainda não há leads com WhatsApp.'}</p>`}
async function openInboxChat(id){const c=state.inbox.find(item=>item.id===id);if(!c)return;state.inboxSelected=id;renderInboxList();const host=$('#inbox-chat');host.innerHTML=`<header class="inbox-chat-head"><span class="avatar">${esc(initials(c.name))}</span><div><h2>${esc(c.name)}</h2><p>${esc(c.city)} · ${esc(c.state)} · ${esc(c.savedByName)}</p></div><button class="btn compact" data-inbox-lead="${esc(id)}">Ver lead</button></header><div class="inbox-thread" id="inbox-thread" role="log" aria-live="polite"><p class="inbox-thread-empty">Carregando mensagens…</p></div><form class="inbox-compose" id="inbox-compose" data-id="${esc(id)}"><label class="field"><span>Mensagem para ${esc(c.name)}</span><textarea name="text" maxlength="3000" placeholder="Escreva sua mensagem" required></textarea></label><button class="btn primary" disabled>${icon('whatsapp')}Enviar</button><p class="form-error" role="alert"></p></form>`;await loadInboxThread(id)}
async function loadInboxThread(id){const thread=$('#inbox-thread'),form=$('#inbox-compose');if(!thread||form.dataset.id!==id)return;try{const result=await api(`/whatsapp/leads/${id}`);if(!thread.isConnected||state.inboxSelected!==id)return;form.querySelector('button').disabled=result.status!=='connected';thread.innerHTML=result.messages.length?result.messages.map(m=>`<article class="wa-bubble ${m.direction==='out'?'out':'in'}"><p>${esc(m.body)}</p><span>${m.direction==='out'?'Enviada por '+esc(m.userName||'vendedor'):'Recebida'} · ${dateTime(m.createdAt)}</span></article>`).join(''):`<p class="inbox-thread-empty">${result.status==='connected'?'Nenhuma mensagem ainda. Escreva a primeira abaixo.':'O WhatsApp da empresa está desconectado. Verifique em Configurações.'}</p>`;thread.scrollTop=thread.scrollHeight}catch(error){if(thread.isConnected)thread.innerHTML=`<p class="inbox-error">${esc(error.message)}</p>`}}
async function refreshInbox(){if(state.view!=='whatsapp')return;try{const r=await api('/whatsapp/conversations');if(state.view!=='whatsapp')return;state.inbox=r.conversations;renderInboxList();if(state.inboxSelected)await loadInboxThread(state.inboxSelected)}catch{}}
document.addEventListener('click',e=>{const contact=e.target.closest('[data-inbox-id]');if(contact)openInboxChat(contact.dataset.inboxId);const lead=e.target.closest('[data-inbox-lead]');if(lead){const id=lead.dataset.inboxLead;navigate('leads').then(()=>detail(id))}},true);
document.addEventListener('input',e=>{if(e.target.id==='inbox-search'){state.inboxQuery=e.target.value;renderInboxList()}},true);
document.addEventListener('submit',async e=>{const form=e.target;if(form.id!=='inbox-compose')return;e.preventDefault();e.stopImmediatePropagation();const button=form.querySelector('button'),error=form.querySelector('.form-error'),body=form.elements.text.value.trim();if(!body)return;button.disabled=true;error.textContent='';try{await api(`/whatsapp/leads/${form.dataset.id}`,'POST',{text:body});form.elements.text.value='';await refreshInbox();await loadInboxThread(form.dataset.id)}catch(err){error.textContent=err.message}finally{button.disabled=false}},true);
